  "title": "Meteor Dodge",
  "description": "A fast-paced game where you steer a spaceship left and right to dodge falling meteors and survive as long as possible.",
  "controls": [
    "Arrow left/right or A/D to move the ship",
    "Avoid meteors; game ends on collision"
  ]
